void ITM_SendChar(uint8_t ch)
{
    DEMCR |= (1 << 24);
    ITM_TRACE_EN |= (1 << 0);
    while(!(ITM_STIMULUS_PORT0 & 1));
    ITM_STIMULUS_PORT0 = ch;
}

extern "C" int __io_putchar(int ch)
{
    ITM_SendChar(ch);
    return ch;
}

